#include <bits/stdc++.h>
using namespace std;

string addBig(const string &a, const string &b) {
    string res;
    int i = (int)a.size() - 1, j = (int)b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        res.push_back(char('0' + s % 10));
        carry = s / 10;
    }
    while (res.size() > 1 && res.back() == '0') res.pop_back();
    reverse(res.begin(), res.end());
    return res;
}

int main() {
    string a, b;
    cin >> a >> b;
    cout << addBig(a, b) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string addAbs(const string &a, const string &b) {
    string res;
    int i = (int)a.size() - 1, j = (int)b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        res.push_back(char('0' + s % 10));
        carry = s / 10;
    }
    while (res.size() > 1 && res.back() == '0') res.pop_back();
    reverse(res.begin(), res.end());
    return res;
}

string subAbs(const string &a, const string &b) {   // 保证 a >= b
    string res;
    int i = (int)a.size() - 1, j = (int)b.size() - 1, borrow = 0;
    while (i >= 0) {
        int s = a[i--] - '0' - borrow;
        if (j >= 0) s -= b[j--] - '0';
        if (s < 0) { s += 10; borrow = 1; } else borrow = 0;
        res.push_back(char('0' + s));
    }
    while (res.size() > 1 && res.back() == '0') res.pop_back();
    reverse(res.begin(), res.end());
    return res;
}

int main() {
    string a, b;
    cin >> a >> b;
    bool na = a[0] == '-', nb = b[0] == '-';
    if (na) a = a.substr(1);
    if (nb) b = b.substr(1);
    string res;
    if (na == nb) {
        res = addAbs(a, b);
        if (na && res != "0") res = "-" + res;
    } else if (a.size() > b.size() || (a.size() == b.size() && a >= b)) {
        res = subAbs(a, b);
        if (na && res != "0") res = "-" + res;
    } else {
        res = subAbs(b, a);
        if (!na && res != "0") res = "-" + res;
    }
    cout << res << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string mulAbs(const string &a, const string &b) {
    vector<int> res(a.size() + b.size(), 0);
    for (int i = (int)a.size() - 1, ia = 0; i >= 0; i--, ia++) {
        for (int j = (int)b.size() - 1, jb = 0; j >= 0; j--, jb++) {
            res[ia + jb] += (a[i] - '0') * (b[j] - '0');
        }
    }
    for (int i = 0; i + 1 < (int)res.size(); i++) {
        res[i + 1] += res[i] / 10;
        res[i] %= 10;
    }
    string out;
    for (int i = (int)res.size() - 1; i >= 0; i--) out.push_back(char('0' + res[i]));
    while (out.size() > 1 && out[0] == '0') out.erase(out.begin());
    return out;
}

int main() {
    string a, b;
    cin >> a >> b;
    bool na = a[0] == '-', nb = b[0] == '-';
    if (na) a = a.substr(1);
    if (nb) b = b.substr(1);
    string res = mulAbs(a, b);
    if (na != nb && res != "0") res = "-" + res;
    cout << res << endl;
    return 0;
}

