int main() {
    long long a, b, c, d, e, f;
    cin >> a >> b >> c >> d >> e >> f;
    long long D = a * e - b * d;
    if (D == 0) { cout << "no solution" << endl; return 0; }
    double x = (double)(c * e - b * f) / D;
    double y = (double)(a * f - c * d) / D;
    if (x == (long long)x) cout << (long long)x << " ";
    else cout << x << " ";
    if (y == (long long)y) cout << (long long)y << endl;
    else cout << y << endl;
    return 0;
}

