int main() {
    int a[3][4];
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 4; j++) cin >> a[i][j];
    int best = a[0][0], bi = 0, bj = 0;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 4; j++) {
