int main() {
    int n;
    cin >> n;
    vector<int> fac;
    int x = n;
    for (int d = 2; (long long)d * d <= x; d++) {
        while (x % d == 0) { fac.push_back(d); x /= d; }   // 不去重
    }
    if (x > 1) fac.push_back(x);
    for (int f : fac) cout << f << ' ';                     // 末尾也有空格
    cout << endl;
    cout << fac.size() << endl;
    return 0;
}

