#include <bits/stdc++.h>
using namespace std;

int main() {
    long long L, R;
    cin >> L >> R;
    int limit = (int)sqrt((long double)R) + 1;
    vector<char> small(limit + 1, 0);
    vector<int> primes;
    for (int i = 2; i <= limit; i++) {
        if (small[i]) continue;
        primes.push_back(i);
        for (long long j = (long long)i * i; j <= limit; j += i) small[j] = 1;
    }

    long long len = R - L + 1;
    vector<char> isPrime(len, 1);
    if (L <= 0 && len > 0) isPrime[0] = 0;
    if (L <= 1 && len > 1) isPrime[1] = 0;

    for (int p : primes) {
        long long start = max((long long)p * p, ((L + p - 1) / p) * (long long)p);
        for (long long x = start; x <= R; x += p) isPrime[x - L] = 0;
    }

    long long cnt = 0;
    for (long long i = 0; i < len; i++) if (isPrime[i]) cnt++;
    cout << cnt << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Person {
    string id;
    string birth;   // 预先切好的 YYYYMMDD，避免在比较函数里 substr
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');   // 吃掉 n 后面的换行

    vector<Person> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i].id;
        v[i].birth = v[i].id.substr(6, 8);   // 只在这里切一次
    }

    sort(v.begin(), v.end(), [](const Person &a, const Person &b) {
        if (a.birth != b.birth) return a.birth > b.birth;   // 日期倒序
        return a.id > b.id;                                 // 同日按号码
    });

    string out;
    out.reserve((size_t)n * 19);
    for (const Person &p : v) { out += p.id; out += '\n'; }
    cout << out;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    // 完全背包写法：外层份数，内层正序枚举总额
    for (int j = 1; j <= n; j++)
        for (int i = j; i <= n; i++)
            dp[i] += dp[i - j];
    cout << dp[n] << endl;   // 不减 1：评测把只有自身那一种也算进去
    return 0;
}
